-- AI 助食 数据库初始化（真实数据版 V5）
-- 数据源: data/dishes.xlsx ｜ 食堂: 荟贤+聚雅 ｜ 生成: 2026-09-30
CREATE DATABASE IF NOT EXISTS ai_food DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE ai_food;
DROP TABLE IF EXISTS dishes;
DROP TABLE IF EXISTS windows;
DROP TABLE IF EXISTS cafeterias;
CREATE TABLE cafeterias (id BIGINT PRIMARY KEY, name VARCHAR(100) NOT NULL);
CREATE TABLE windows (id BIGINT PRIMARY KEY, cafeteria_id BIGINT NOT NULL, floor TINYINT NOT NULL, name VARCHAR(100) NOT NULL, INDEX idx_cafeteria_floor (cafeteria_id, floor));
CREATE TABLE dishes (id BIGINT PRIMARY KEY, name VARCHAR(100) NOT NULL, window_id BIGINT NOT NULL, price DECIMAL(6,2) NOT NULL, rating DECIMAL(3,1) NOT NULL DEFAULT 0, count INT NOT NULL DEFAULT 0, taste VARCHAR(20), ingredients VARCHAR(200), kcal INT, protein DECIMAL(5,1), fat DECIMAL(5,1), carbs DECIMAL(5,1), crop TINYINT, image_url VARCHAR(200), INDEX idx_window_id (window_id));

-- 菜品封面采用 dist/dish-images/{三位数菜品ID}.jpg；缺图菜品由前端默认图兜底。
UPDATE dishes SET image_url = CONCAT(LPAD(id, 3, '0'), '.jpg');
